-- =====================================================================
-- THE LABELS
--
-- Staged first, then resolved. The first attempt inserted 35,871
-- rows in ONE statement with a subquery per row, and the server
-- died on it - 36,000 subqueries in a single INSERT is more than
-- it will plan. Staging and resolving separately is both faster
-- and it lets the resolution be checked.
-- =====================================================================

CREATE TEMP TABLE _vocab_label_stage (
  vocabulary   text NOT NULL,
  value_key    text NOT NULL,
  language     text NOT NULL,
  name         text NOT NULL,
  source       text,
  source_ref   text
) ON COMMIT DROP;

-- country (1787 label rows)
;

-- region (30186 label rows)
;

-- cuisine (1090 label rows)
;

-- family (487 label rows)
;

-- technique (183 label rows)
;

-- tradition (1811 label rows)
;

-- context (37 label rows)
;

-- ingredient_category (266 label rows)
;

-- predicate (24 label rows)
;

-- Resolve each staged row to its value's id, by the value's own key.
-- A row whose key does not resolve is DROPPED, not left dangling.
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'country'
   AND NOT EXISTS (SELECT 1 FROM geo_entities t
                    WHERE t.iso_code = s.value_key AND entity_type = 'country');
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'region'
   AND NOT EXISTS (SELECT 1 FROM geo_entities t
                    WHERE t.iso_code = s.value_key AND entity_type = 'region');
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'cuisine'
   AND NOT EXISTS (SELECT 1 FROM dish_cuisines t
                    WHERE t.slug = s.value_key);
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'family'
   AND NOT EXISTS (SELECT 1 FROM dish_families t
                    WHERE t.slug = s.value_key);
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'technique'
   AND NOT EXISTS (SELECT 1 FROM dish_techniques t
                    WHERE t.slug = s.value_key);
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'tradition'
   AND NOT EXISTS (SELECT 1 FROM dish_traditions t
                    WHERE t.slug = s.value_key);
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'context'
   AND NOT EXISTS (SELECT 1 FROM dish_contexts t
                    WHERE t.slug = s.value_key);
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'ingredient_category'
   AND NOT EXISTS (SELECT 1 FROM ingredient_categories t
                    WHERE t.slug = s.value_key);
DELETE FROM _vocab_label_stage s
 WHERE s.vocabulary = 'predicate'
   AND NOT EXISTS (SELECT 1 FROM relation_types t
                    WHERE t.slug = s.value_key);

-- resolve the country labels against geo_entities
SELECT s.vocabulary, t.id, s.language, s.name, false, s.source, s.source_ref
  FROM _vocab_label_stage s
  JOIN geo_entities t ON t.iso_code = s.value_key AND entity_type = 'country'
 WHERE s.vocabulary = 'country'
ON CONFLICT (vocabulary, value_id, language) DO UPDATE SET
  name = EXCLUDED.name,
  source = EXCLUDED.source,
  source_ref = EXCLUDED.source_ref;

-- resolve the region labels against geo_entities
SELECT s.vocabulary, t.id, s.language, s.name, false, s.source, s.source_ref
  FROM _vocab_label_stage s
  JOIN geo_entities t ON t.iso_code = s.value_key AND entity_type = 'region'
 WHERE s.vocabulary = 'region'
ON CONFLICT (vocabulary, value_id, language) DO UPDATE SET
  name = EXCLUDED.name,
  source = EXCLUDED.source,
  source_ref = EXCLUDED.source_ref;

